90	    /// It matches the given string against the stored patterns.
91	    ///
92	    /// It returns [true] if there's at least a match
93	    pub fn matches(&self, source: &str) -> bool {
94	        let mut already_ignored = self.already_checked.write().unwrap();
95	        if let Some(matches) = already_ignored.get(source) {
96	            return *matches;
97	        }
98	        for pattern in &self.patterns {
99	            if pattern.matches_with(source, self.options) || source.contains(pattern.as_str()) {
100	                already_ignored.insert(source.to_string(), true);
101	                return true;
102	            }
103	        }
104	        already_ignored.insert(source.to_string(), false);
105	        false
106	    }
